1	package server
2	
3	import (
4		"math"
5		"net/http"
6		"sort"
7		"sync"
8	)
9	
10	// deviceInput is one member of a create-pool request.
11	type deviceInput struct {
12		ID            string `json:"id"`
13		CapacityBytes int64  `json:"capacityBytes"`
14		FaultDomain   string `json:"faultDomain"`
15	}
16	
17	type createPoolInput struct {
18		ID      string        `json:"id"`
19		Devices []deviceInput `json:"devices"`
20	}
21	
22	type reservationInput struct {
23		RequestID string `json:"requestId"`
24		Bytes     int64  `json:"bytes"`
25	}
26	
27	// deviceView is the public representation of a pool device.
28	type deviceView struct {
29		ID            string `json:"id"`
30		CapacityBytes int64  `json:"capacityBytes"`
31		FaultDomain   string `json:"faultDomain"`
32	}
33	
34	// poolView is the public representation of a storage pool.
35	type poolView struct {
36		ID               string       `json:"id"`
37		Devices          []deviceView `json:"devices"`
38		RawCapacityBytes int64        `json:"rawCapacityBytes"`
39		AllocatedBytes   int64        `json:"allocatedBytes"`
40		AvailableBytes   int64        `json:"availableBytes"`
41	}
42	
43	// reservationView is the result of a successful reservation request.
44	type reservationView struct {
45		PoolID    string `json:"poolId"`
46		RequestID string `json:"requestId"`
47		Bytes     int64  `json:"bytes"`
48	}
49	
50	type reservation struct {
51		requestID string
52		bytes     int64
53	}
54	
55	type pool struct {
56		id            string
57		devices       []deviceInput
58		rawCapacity   int64
59		reservations  map[string]reservation
60		volumeBytes   int64 // total sizeBytes of volumes in this pool
61		snapshotBytes int64 // total sizeBytes of snapshots held in this pool
62		objectBytes   int64 // total sizeBytes of objects in buckets of this pool
63	}
64	
65	// volume is a capacity allocation inside a pool with an optional exclusive
66	// node binding. generation is bumped on every binding state change.
67	// cloneSource records the snapshot a volume was cloned from ("" for a volume
68	// created directly) so clone retries can be told apart from foreign ids.
69	type volume struct {
70		id          string
71		poolID      string
72		sizeBytes   int64
73		generation  int64
74		binding     string // "" when unbound
75		cloneSource string // snapshot id when produced via a clone
76	}
77	
78	func (p *pool) allocated() int64 {
79		var total int64 = p.volumeBytes + p.snapshotBytes + p.objectBytes
80		for _, r := range p.reservations {
81			total += r.bytes
82		}
83		return total
84	}
85	
86	func (p *pool) view() poolView {
87		devices := make([]deviceView, len(p.devices))
88		for i, d := range p.devices {
89			devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
90		}
91		allocated := p.allocated()
92		return poolView{
93			ID:               p.id,
94			Devices:          devices,
95			RawCapacityBytes: p.rawCapacity,
96			AllocatedBytes:   allocated,
97			AvailableBytes:   p.rawCapacity - allocated,
98		}
99	}
100	
101	// store is the in-memory state of the service. It is wiped on restart.
102	type store struct {
103		mu          sync.RWMutex
104		pools       map[string]*pool
105		volumes     map[string]*volume
106		snapshots   map[string]*snapshot
107		buckets     map[string]*bucket
108		deviceOwner map[string]string
109		// auditEvents is the append-only audit log; auditSeq is the sequence of
110		// its last entry (0 while empty). Both are mutated under mu, together with
111		// the business state each event describes.
112		auditEvents []auditEvent
113		auditSeq    int64
114	}
115	
116	func newStore() *store {
117		return &store{
118			pools:       make(map[string]*pool),
119			volumes:     make(map[string]*volume),
120			snapshots:   make(map[string]*snapshot),
121			buckets:     make(map[string]*bucket),
122			deviceOwner: make(map[string]string),
123		}
124	}
125	
126	func validID(id string) bool {
127		return idPattern.MatchString(id)
128	}
129	
130	func (s *store) listPools(w http.ResponseWriter) {
131		s.mu.RLock()
132		ids := make([]string, 0, len(s.pools))
133		for id := range s.pools {
134			ids = append(ids, id)
135		}
136		sort.Strings(ids)
137		items := make([]poolView, 0, len(ids))
138		for _, id := range ids {
139			items = append(items, s.pools[id].view())
140		}
141		s.mu.RUnlock()
142		writeJSON(w, http.StatusOK, map[string]any{"items": items})
143	}
144	
145	func (s *store) getPool(w http.ResponseWriter, id string) {
146		if !validID(id) {
147			writeError(w, http.StatusBadRequest, "invalid_request")
148			return
149		}
150		s.mu.RLock()
151		p, ok := s.pools[id]
152		var v poolView
153		if ok {
154			v = p.view()
155		}
156		s.mu.RUnlock()
157		if !ok {
158			writeError(w, http.StatusNotFound, "pool_not_found")
159			return
160		}
161		writeJSON(w, http.StatusOK, v)
162	}
163	
164	func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
165		var in createPoolInput
166		if !decodeRequest(r, &in) {
167			writeError(w, http.StatusBadRequest, "invalid_request")
168			return
169		}
170		// Validate the whole payload before touching any state so a failure
171		// never leaves a partial pool behind.
172		if !validID(in.ID) || len(in.Devices) == 0 {
173			writeError(w, http.StatusBadRequest, "invalid_request")
174			return
175		}
176		seen := make(map[string]bool, len(in.Devices))
177		var rawCapacity int64
178		for _, d := range in.Devices {
179			if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
180				writeError(w, http.StatusBadRequest, "invalid_request")
181				return
182			}
183			if rawCapacity > math.MaxInt64-d.CapacityBytes {
184				writeError(w, http.StatusBadRequest, "invalid_request")
185				return
186			}
187			seen[d.ID] = true
188			rawCapacity += d.CapacityBytes
189		}
190	
191		s.mu.Lock()
192		defer s.mu.Unlock()
193		if _, ok := s.pools[in.ID]; ok {
194			writeError(w, http.StatusConflict, "pool_exists")
195			return
196		}
197		for _, d := range in.Devices {
198			if _, busy := s.deviceOwner[d.ID]; busy {
199				writeError(w, http.StatusConflict, "device_in_use")
200				return
201			}
202		}
203	
204		devices := append([]deviceInput(nil), in.Devices...)
205		p := &pool{
206			id:           in.ID,
207			devices:      devices,
208			rawCapacity:  rawCapacity,
209			reservations: make(map[string]reservation),
210		}
211		s.pools[in.ID] = p
212		for _, d := range devices {
213			s.deviceOwner[d.ID] = in.ID
214		}
215		s.appendAudit(auditPoolCreated, storagePoolPath+"/"+in.ID, in.ID, 0)
216		writeJSON(w, http.StatusCreated, p.view())
217	}
218	
219	func (s *store) deletePool(w http.ResponseWriter, id string) {
220		if !validID(id) {
221			writeError(w, http.StatusBadRequest, "invalid_request")
222			return
223		}
224		s.mu.Lock()
225		defer s.mu.Unlock()
226		p, ok := s.pools[id]
227		if !ok {
228			writeError(w, http.StatusNotFound, "pool_not_found")
229			return
230		}
231		if len(p.reservations) > 0 || p.volumeBytes > 0 || p.snapshotBytes > 0 || p.objectBytes > 0 {
232			writeError(w, http.StatusConflict, "pool_not_empty")
233			return
234		}
235		// An empty bucket still blocks pool deletion even though it charges no
236		// bytes.
237		for _, b := range s.buckets {
238			if b.poolID == id {
239				writeError(w, http.StatusConflict, "pool_not_empty")
240				return
241			}
242		}
243		for _, d := range p.devices {
244			delete(s.deviceOwner, d.ID)
245		}
246		delete(s.pools, id)
247		s.appendAudit(auditPoolDeleted, storagePoolPath+"/"+id, id, 0)
248		w.WriteHeader(http.StatusNoContent)
249	}
250	
251	func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
252		var in reservationInput
253		if !decodeRequest(r, &in) {
254			writeError(w, http.StatusBadRequest, "invalid_request")
255			return
256		}
257		if !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
258			writeError(w, http.StatusBadRequest, "invalid_request")
259			return
260		}
261	
262		s.mu.Lock()
263		defer s.mu.Unlock()
264		p, ok := s.pools[poolID]
265		if !ok {
266			writeError(w, http.StatusNotFound, "pool_not_found")
267			return
268		}
269		if existing, dup := p.reservations[in.RequestID]; dup {
270			if existing.bytes != in.Bytes {
271				writeError(w, http.StatusConflict, "idempotency_conflict")
272				return
273			}
274			writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
275			return
276		}
277		allocated := p.allocated()
278		if allocated > p.rawCapacity-in.Bytes {
279			writeError(w, http.StatusConflict, "insufficient_capacity")
280			return
281		}
282		p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes}
283		s.appendAudit(auditReservationCreated,
284			storagePoolPath+"/"+poolID+"/reservations/"+in.RequestID, poolID, in.Bytes)
285		writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
286	}
287	
288	func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
289		if !validID(poolID) || !validID(requestID) {
290			writeError(w, http.StatusBadRequest, "invalid_request")
291			return
292		}
293		s.mu.Lock()
294		defer s.mu.Unlock()
295		p, ok := s.pools[poolID]
296		if !ok {
297			writeError(w, http.StatusNotFound, "pool_not_found")
298			return
299		}
300		// Deleting an unknown or already-deleted reservation is a success with
301		// no state change, so only a real deletion records an event.
302		if r, existed := p.reservations[requestID]; existed {
303			delete(p.reservations, requestID)
304			s.appendAudit(auditReservationDeleted,
305				storagePoolPath+"/"+poolID+"/reservations/"+requestID, poolID, -r.bytes)
306		}
307		w.WriteHeader(http.StatusNoContent)
308	}
