package server

import (
	"math"
	"net/http"
	"sort"
	"sync"
)

// deviceInput is one member of a create-pool request.
type deviceInput struct {
	ID            string `json:"id"`
	CapacityBytes int64  `json:"capacityBytes"`
	FaultDomain   string `json:"faultDomain"`
}

type createPoolInput struct {
	ID      string        `json:"id"`
	Devices []deviceInput `json:"devices"`
}

type reservationInput struct {
	RequestID string `json:"requestId"`
	Bytes     int64  `json:"bytes"`
}

// deviceView is the public representation of a pool device.
type deviceView struct {
	ID            string `json:"id"`
	CapacityBytes int64  `json:"capacityBytes"`
	FaultDomain   string `json:"faultDomain"`
}

// poolView is the public representation of a storage pool.
type poolView struct {
	ID               string       `json:"id"`
	Devices          []deviceView `json:"devices"`
	RawCapacityBytes int64        `json:"rawCapacityBytes"`
	AllocatedBytes   int64        `json:"allocatedBytes"`
	AvailableBytes   int64        `json:"availableBytes"`
}

// reservationView is the result of a successful reservation request.
type reservationView struct {
	PoolID    string `json:"poolId"`
	RequestID string `json:"requestId"`
	Bytes     int64  `json:"bytes"`
}

type reservation struct {
	requestID string
	bytes     int64
}

type pool struct {
	id            string
	devices       []deviceInput
	rawCapacity   int64
	reservations  map[string]reservation
	volumeBytes   int64 // total sizeBytes of volumes in this pool
	snapshotBytes int64 // total sizeBytes of snapshots held in this pool
	objectBytes   int64 // total sizeBytes of objects in buckets of this pool
}

// volume is a capacity allocation inside a pool with an optional exclusive
// node binding. generation is bumped on every binding state change.
// cloneSource records the snapshot a volume was cloned from ("" for a volume
// created directly) so clone retries can be told apart from foreign ids.
type volume struct {
	id          string
	poolID      string
	sizeBytes   int64
	generation  int64
	binding     string // "" when unbound
	cloneSource string // snapshot id when produced via a clone
}

func (p *pool) allocated() int64 {
	var total int64 = p.volumeBytes + p.snapshotBytes + p.objectBytes
	for _, r := range p.reservations {
		total += r.bytes
	}
	return total
}

func (p *pool) view() poolView {
	devices := make([]deviceView, len(p.devices))
	for i, d := range p.devices {
		devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
	}
	allocated := p.allocated()
	return poolView{
		ID:               p.id,
		Devices:          devices,
		RawCapacityBytes: p.rawCapacity,
		AllocatedBytes:   allocated,
		AvailableBytes:   p.rawCapacity - allocated,
	}
}

// store is the in-memory state of the service. It is wiped on restart.
type store struct {
	mu          sync.RWMutex
	pools       map[string]*pool
	volumes     map[string]*volume
	snapshots   map[string]*snapshot
	buckets     map[string]*bucket
	deviceOwner map[string]string
	// auditEvents is the append-only audit log; auditSeq is the sequence of
	// its last entry (0 while empty). Both are mutated under mu, together with
	// the business state each event describes.
	auditEvents []auditEvent
	auditSeq    int64
}

func newStore() *store {
	return &store{
		pools:       make(map[string]*pool),
		volumes:     make(map[string]*volume),
		snapshots:   make(map[string]*snapshot),
		buckets:     make(map[string]*bucket),
		deviceOwner: make(map[string]string),
	}
}

func validID(id string) bool {
	return idPattern.MatchString(id)
}

func (s *store) listPools(w http.ResponseWriter) {
	s.mu.RLock()
	ids := make([]string, 0, len(s.pools))
	for id := range s.pools {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	items := make([]poolView, 0, len(ids))
	for _, id := range ids {
		items = append(items, s.pools[id].view())
	}
	s.mu.RUnlock()
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *store) getPool(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.RLock()
	p, ok := s.pools[id]
	var v poolView
	if ok {
		v = p.view()
	}
	s.mu.RUnlock()
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	writeJSON(w, http.StatusOK, v)
}

func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
	var in createPoolInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	// Validate the whole payload before touching any state so a failure
	// never leaves a partial pool behind.
	if !validID(in.ID) || len(in.Devices) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	seen := make(map[string]bool, len(in.Devices))
	var rawCapacity int64
	for _, d := range in.Devices {
		if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
			writeError(w, http.StatusBadRequest, "invalid_request")
			return
		}
		if rawCapacity > math.MaxInt64-d.CapacityBytes {
			writeError(w, http.StatusBadRequest, "invalid_request")
			return
		}
		seen[d.ID] = true
		rawCapacity += d.CapacityBytes
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.pools[in.ID]; ok {
		writeError(w, http.StatusConflict, "pool_exists")
		return
	}
	for _, d := range in.Devices {
		if _, busy := s.deviceOwner[d.ID]; busy {
			writeError(w, http.StatusConflict, "device_in_use")
			return
		}
	}

	devices := append([]deviceInput(nil), in.Devices...)
	p := &pool{
		id:           in.ID,
		devices:      devices,
		rawCapacity:  rawCapacity,
		reservations: make(map[string]reservation),
	}
	s.pools[in.ID] = p
	for _, d := range devices {
		s.deviceOwner[d.ID] = in.ID
	}
	s.appendAudit(auditPoolCreated, storagePoolPath+"/"+in.ID, in.ID, 0)
	writeJSON(w, http.StatusCreated, p.view())
}

func (s *store) deletePool(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.pools[id]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	if len(p.reservations) > 0 || p.volumeBytes > 0 || p.snapshotBytes > 0 || p.objectBytes > 0 {
		writeError(w, http.StatusConflict, "pool_not_empty")
		return
	}
	// An empty bucket still blocks pool deletion even though it charges no
	// bytes.
	for _, b := range s.buckets {
		if b.poolID == id {
			writeError(w, http.StatusConflict, "pool_not_empty")
			return
		}
	}
	for _, d := range p.devices {
		delete(s.deviceOwner, d.ID)
	}
	delete(s.pools, id)
	s.appendAudit(auditPoolDeleted, storagePoolPath+"/"+id, id, 0)
	w.WriteHeader(http.StatusNoContent)
}

func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
	var in reservationInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.pools[poolID]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	if existing, dup := p.reservations[in.RequestID]; dup {
		if existing.bytes != in.Bytes {
			writeError(w, http.StatusConflict, "idempotency_conflict")
			return
		}
		writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
		return
	}
	allocated := p.allocated()
	if allocated > p.rawCapacity-in.Bytes {
		writeError(w, http.StatusConflict, "insufficient_capacity")
		return
	}
	p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes}
	s.appendAudit(auditReservationCreated,
		storagePoolPath+"/"+poolID+"/reservations/"+in.RequestID, poolID, in.Bytes)
	writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
}

func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
	if !validID(poolID) || !validID(requestID) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.pools[poolID]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	// Deleting an unknown or already-deleted reservation is a success with
	// no state change, so only a real deletion records an event.
	if r, existed := p.reservations[requestID]; existed {
		delete(p.reservations, requestID)
		s.appendAudit(auditReservationDeleted,
			storagePoolPath+"/"+poolID+"/reservations/"+requestID, poolID, -r.bytes)
	}
	w.WriteHeader(http.StatusNoContent)
}

// Package server exposes the frozen public surface of VaultGrid.
//
// In addition to process health, it serves the storage-pool, capacity
// reservation and volume lifecycle HTTP API described in README.md. The
// exported surface (Handler, Version, VAULTGRID_ADDR handling) stays
// backward compatible.
package server

import (
	"encoding/json"
	"io"
	"net/http"
	"regexp"
	"strings"
)

// Version is the release identifier.
const Version = "0.1.0"

// idPattern restricts every client-supplied id: 1..64 letters, digits,
// dots, underscores or hyphens.
var idPattern = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)

type health struct {
	Status  string `json:"status"`
	Service string `json:"service"`
	Version string `json:"version"`
}

// Handler returns the HTTP surface served by VaultGrid.
//
// Dispatch is a plain handler rather than http.ServeMux: the mux cleans
// paths (collapsing "//" and resolving "..") before they reach the handler,
// which would corrupt object keys, since a key is the raw remainder of the
// path after "objects/".
func Handler() http.Handler {
	s := newStore()
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/healthz" {
			if r.Method != http.MethodGet {
				w.Header().Set("Allow", http.MethodGet)
				writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
				return
			}
			w.Header().Set("Content-Type", "application/json; charset=utf-8")
			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "vaultgrid", Version: Version})
			return
		}
		s.route(w, r)
	})
}

const (
	storagePoolPath    = "/v1/storage-pools"
	volumePath         = "/v1/volumes"
	snapshotPath       = "/v1/snapshots"
	bucketPath         = "/v1/buckets"
	capacityReportPath = "/v1/capacity-report"
)

// route dispatches every non-healthz request. Paths it does not recognise
// answer 404/not_found; recognised paths with the wrong verb answer 405.
func (s *store) route(w http.ResponseWriter, r *http.Request) {
	switch {
	case r.URL.Path == volumePath || strings.HasPrefix(r.URL.Path, volumePath+"/"):
		s.routeVolumes(w, r)
	case r.URL.Path == snapshotPath || strings.HasPrefix(r.URL.Path, snapshotPath+"/"):
		s.routeSnapshots(w, r)
	case r.URL.Path == storagePoolPath || strings.HasPrefix(r.URL.Path, storagePoolPath+"/"):
		s.routeStoragePools(w, r)
	case r.URL.Path == bucketPath || strings.HasPrefix(r.URL.Path, bucketPath+"/"):
		s.routeBuckets(w, r)
	case r.URL.Path == capacityReportPath:
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		s.capacityReport(w, r)
	case strings.HasPrefix(r.URL.Path, capacityReportPath+"/"):
		writeError(w, http.StatusNotFound, "not_found")
	case r.URL.Path == auditEventsPath:
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		s.listAuditEvents(w, r)
	case strings.HasPrefix(r.URL.Path, auditEventsPath+"/"):
		writeError(w, http.StatusNotFound, "not_found")
	default:
		writeError(w, http.StatusNotFound, "not_found")
	}
}

// routeStoragePools dispatches /v1/storage-pools and its sub-paths.
func (s *store) routeStoragePools(w http.ResponseWriter, r *http.Request) {
	parts := splitPath(r.URL.Path, storagePoolPath)
	for _, seg := range parts {
		if seg == "" {
			writeError(w, http.StatusNotFound, "not_found")
			return
		}
	}
	switch {
	case len(parts) == 0:
		switch r.Method {
		case http.MethodGet:
			s.listPools(w)
		case http.MethodPost:
			s.createPool(w, r)
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodPost)
		}
	case len(parts) == 1:
		switch r.Method {
		case http.MethodGet:
			s.getPool(w, parts[0])
		case http.MethodDelete:
			s.deletePool(w, parts[0])
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodDelete)
		}
	case len(parts) == 2 && parts[1] == "reservations":
		if r.Method != http.MethodPost {
			methodNotAllowed(w, http.MethodPost)
			return
		}
		s.createReservation(w, r, parts[0])
	case len(parts) == 3 && parts[1] == "reservations":
		if r.Method != http.MethodDelete {
			methodNotAllowed(w, http.MethodDelete)
			return
		}
		s.deleteReservation(w, parts[0], parts[2])
	default:
		writeError(w, http.StatusNotFound, "not_found")
	}
}

// splitPath splits the tail after prefix into path segments.
func splitPath(path, prefix string) []string {
	rest := strings.TrimPrefix(path, prefix)
	if rest == "" {
		return nil
	}
	segments := strings.Split(rest, "/")
	// Drop the single empty segment introduced by the leading slash, but
	// keep trailing/inner empty segments so the caller can reject them 404.
	if segments[0] == "" {
		segments = segments[1:]
	}
	return segments
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code string) {
	writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
}

func methodNotAllowed(w http.ResponseWriter, allowed ...string) {
	w.Header().Set("Allow", strings.Join(allowed, ", "))
	writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
}

// decodeRequest parses exactly one JSON value, rejecting unknown fields and
// any trailing content so malformed bodies cannot partially apply.
func decodeRequest(r *http.Request, v any) bool {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		return false
	}
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		return false
	}
	return true
}

