18	const metaPrefix = "X-Vaultgrid-Meta-"
19	
20	type createBucketInput struct {
21		ID     string `json:"id"`
22		PoolID string `json:"poolId"`
23	}
24	
25	// bucketView is the public representation of a bucket.
26	type bucketView struct {
27		ID          string `json:"id"`
28		PoolID      string `json:"poolId"`
29		ObjectCount int    `json:"objectCount"`
30		BytesUsed   int64  `json:"bytesUsed"`
31	}
32	
33	// objectView is the public representation of an object after a write, and
34	// the summary shape used in object listings.
35	type objectView struct {
36		Key       string            `json:"key"`
37		SizeBytes int64             `json:"sizeBytes"`
38		Metadata  map[string]string `json:"metadata"`
39		ETag      string            `json:"etag"`
40	}
41	
42	// bucket is a namespace of objects bound to one pool. bytesUsed is kept in
43	// sync with the sum of its objects' sizes; the same total is charged to the
44	// pool as objectBytes.
45	type bucket struct {
46		id      string
47		poolID  string
48		objects map[string]*object
49	}
50	
51	func (b *bucket) bytesUsed() int64 {
52		var total int64
53		for _, o := range b.objects {
54			total += o.sizeBytes
55		}
56		return total
57	}
58	
59	func (b *bucket) view() bucketView {
60		return bucketView{ID: b.id, PoolID: b.poolID, ObjectCount: len(b.objects), BytesUsed: b.bytesUsed()}
61	}
62	
63	// object is a stored byte sequence with user metadata. etag is the quoted
64	// lowercase hex SHA-256 of content.
65	type object struct {
66		key       string
67		content   []byte
68		metadata  map[string]string
69		etag      string
70		sizeBytes int64
71	}
72	
73	func (o *object) view() objectView {
74		return objectView{Key: o.key, SizeBytes: o.sizeBytes, Metadata: o.metadata, ETag: o.etag}
75	}
76	
77	// routeBuckets dispatches /v1/buckets and its sub-paths. The object key is
78	// the remainder of the path after "objects/" (already URL-decoded once by
79	// the net/http layer) and may contain slashes, so it is not split here.
80	func (s *store) routeBuckets(w http.ResponseWriter, r *http.Request) {
81		rest := strings.TrimPrefix(r.URL.Path, bucketPath)
82		if rest == "" {
83			switch r.Method {
84			case http.MethodGet:
85				s.listBuckets(w)
86			case http.MethodPost:
87				s.createBucket(w, r)
88			default:
89				methodNotAllowed(w, http.MethodGet, http.MethodPost)
90			}
91			return
92		}
93		// rest begins with "/"; the bucket id is the single next segment.
94		bucketID, tail, found := strings.Cut(rest[1:], "/")
95		if bucketID == "" {
96			writeError(w, http.StatusNotFound, "not_found")
97			return
98		}
99		if !found {
100			switch r.Method {
101			case http.MethodGet:
102				s.getBucket(w, bucketID)
103			case http.MethodDelete:
104				s.deleteBucket(w, bucketID)
105			default:
106				methodNotAllowed(w, http.MethodGet, http.MethodDelete)
107			}
108			return
109		}
110		if tail == "objects" {
111			if r.Method != http.MethodGet {
112				methodNotAllowed(w, http.MethodGet)
113				return
114			}
115			s.listObjects(w, r, bucketID)
116			return
117		}
118		if key, ok := strings.CutPrefix(tail, "objects/"); ok {
119			switch r.Method {
120			case http.MethodPut:
121				s.putObject(w, r, bucketID, key)
122			case http.MethodGet:
123				s.getObject(w, r, bucketID, key, false)
124			case http.MethodHead:
125				s.getObject(w, r, bucketID, key, true)
126			case http.MethodDelete:
127				s.deleteObject(w, r, bucketID, key)
128			default:
129				methodNotAllowed(w, http.MethodPut, http.MethodGet, http.MethodHead, http.MethodDelete)
130			}
131			return
132		}
133		writeError(w, http.StatusNotFound, "not_found")
134	}
135	
136	func (s *store) listBuckets(w http.ResponseWriter) {
137		s.mu.RLock()
138		ids := make([]string, 0, len(s.buckets))
139		for id := range s.buckets {
140			ids = append(ids, id)
141		}
142		sort.Strings(ids)
143		items := make([]bucketView, 0, len(ids))
144		for _, id := range ids {
145			items = append(items, s.buckets[id].view())
146		}
147		s.mu.RUnlock()
148		writeJSON(w, http.StatusOK, map[string]any{"items": items})
149	}
150	
151	func (s *store) getBucket(w http.ResponseWriter, id string) {
152		if !validID(id) {
153			writeError(w, http.StatusBadRequest, "invalid_request")
154			return
155		}
156		s.mu.RLock()
157		b, ok := s.buckets[id]
158		var v bucketView
159		if ok {
160			v = b.view()
161		}
162		s.mu.RUnlock()
163		if !ok {
164			writeError(w, http.StatusNotFound, "bucket_not_found")
165			return
166		}
167		writeJSON(w, http.StatusOK, v)
168	}
169	
170	func (s *store) createBucket(w http.ResponseWriter, r *http.Request) {
171		var in createBucketInput
172		if !decodeRequest(r, &in) {
173			writeError(w, http.StatusBadRequest, "invalid_request")
174			return
175		}
176		if !validID(in.ID) || !validID(in.PoolID) {
177			writeError(w, http.StatusBadRequest, "invalid_request")
178			return
179		}
180	
181		s.mu.Lock()
182		defer s.mu.Unlock()
183		if existing, dup := s.buckets[in.ID]; dup {
184			if existing.poolID == in.PoolID {
185				writeJSON(w, http.StatusOK, existing.view())
186				return
187			}
188			writeError(w, http.StatusConflict, "bucket_exists")
189			return
190		}
191		if _, ok := s.pools[in.PoolID]; !ok {
192			writeError(w, http.StatusNotFound, "pool_not_found")
193			return
194		}
195		s.buckets[in.ID] = &bucket{id: in.ID, poolID: in.PoolID, objects: make(map[string]*object)}
196		s.appendAudit(auditBucketCreated, bucketPath+"/"+in.ID, in.PoolID, 0)
197		writeJSON(w, http.StatusCreated, s.buckets[in.ID].view())
198	}
199	
200	func (s *store) deleteBucket(w http.ResponseWriter, id string) {
201		if !validID(id) {
202			writeError(w, http.StatusBadRequest, "invalid_request")
203			return
204		}
205		s.mu.Lock()
206		defer s.mu.Unlock()
207		b, ok := s.buckets[id]
208		if !ok {
209			writeError(w, http.StatusNotFound, "bucket_not_found")
210			return
211		}
212		if len(b.objects) > 0 {
213			writeError(w, http.StatusConflict, "bucket_not_empty")
214			return
215		}
216		delete(s.buckets, id)
217		s.appendAudit(auditBucketDeleted, bucketPath+"/"+id, b.poolID, 0)
218		w.WriteHeader(http.StatusNoContent)
219	}
220	
221	// validObjectKey reports whether key is 1..1024 bytes of valid UTF-8 with no
222	// control characters.
223	func validObjectKey(key string) bool {
224		if len(key) == 0 || len(key) > 1024 || !utf8.ValidString(key) {
225			return false
226		}
227		for _, r := range key {
228			if unicode.IsControl(r) {
229				return false
230			}
231		}
232		return true
233	}
234	
235	// extractMetadata collects the X-Vaultgrid-Meta-* request headers into a
236	// metadata map keyed by the suffix after the prefix. A header with an empty
237	// suffix or a value that is not valid UTF-8 or carries control characters
238	// makes the whole request invalid.
239	func extractMetadata(h http.Header) (map[string]string, bool) {
240		meta := make(map[string]string)
241		for name, values := range h {
242			suffix, ok := strings.CutPrefix(name, metaPrefix)
243			if !ok {
244				continue
245			}
246			if suffix == "" {
247				return nil, false
248			}
249			for _, v := range values {
250				if !utf8.ValidString(v) {
251					return nil, false
252				}
253				for _, r := range v {
254					if unicode.IsControl(r) {
255						return nil, false
256					}
257				}
258			}
259			meta[suffix] = strings.Join(values, ", ")
260		}
261		return meta, true
262	}
263	
264	// parsePrecondition validates the conditional-write headers. It returns the
265	// If-Match etag ("" when absent) and whether If-None-Match: * was given. ok
266	// is false when both headers are present or either has an unsupported form.
267	func parsePrecondition(h http.Header) (ifMatch string, ifNoneMatchStar, ok bool) {
268		matches, hasMatch := h["If-Match"]
269		noneMatches, hasNoneMatch := h["If-None-Match"]
270		if hasMatch && hasNoneMatch {
271			return "", false, false
272		}
273		if hasMatch {
274			if len(matches) != 1 || !isQuotedETag(matches[0]) {
275				return "", false, false
276			}
277			return matches[0], false, true
278		}
279		if hasNoneMatch {
280			if len(noneMatches) != 1 || noneMatches[0] != "*" {
281				return "", false, false
282			}
283			return "", true, true
284		}
285		return "", false, true
286	}
287	
288	// isQuotedETag reports whether v looks like a quoted hex etag, e.g.
289	// "9f86d081...". The content is not checked against any object here.
290	func isQuotedETag(v string) bool {
291		if len(v) < 2 || v[0] != '"' || v[len(v)-1] != '"' {
292			return false
293		}
294		inner := v[1 : len(v)-1]
295		if inner == "" {
296			return false
297		}
298		for _, c := range inner {
299			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
300				return false
301			}
302		}
303		return true
304	}
305	
306	func etagOf(content []byte) string {
307		sum := sha256.Sum256(content)
308		return `"` + hex.EncodeToString(sum[:]) + `"`
309	}
310	
311	func (s *store) putObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
312		if !validID(bucketID) || !validObjectKey(key) {
313			writeError(w, http.StatusBadRequest, "invalid_request")
314			return
315		}
316		if r.URL.RawQuery != "" {
317			writeError(w, http.StatusBadRequest, "invalid_request")
318			return
319		}
320		metadata, ok := extractMetadata(r.Header)
321		if !ok {
322			writeError(w, http.StatusBadRequest, "invalid_request")
323			return
324		}
325		ifMatch, ifNoneMatchStar, ok := parsePrecondition(r.Header)
326		if !ok {
327			writeError(w, http.StatusBadRequest, "invalid_request")
328			return
329		}
330		content, err := io.ReadAll(r.Body)
331		if err != nil {
332			writeError(w, http.StatusBadRequest, "invalid_request")
333			return
334		}
335		etag := etagOf(content)
336		size := int64(len(content))
337	
338		s.mu.Lock()
339		defer s.mu.Unlock()
340		b, ok := s.buckets[bucketID]
341		if !ok {
342			writeError(w, http.StatusNotFound, "bucket_not_found")
343			return
344		}
345		existing := b.objects[key]
346		if ifMatch != "" && (existing == nil || existing.etag != ifMatch) {
347			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
348			return
349		}
350		if ifNoneMatchStar && existing != nil {
351			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
352			return
353		}
354		var oldSize int64
355		if existing != nil {
356			oldSize = existing.sizeBytes
357		}
358		p := s.pools[b.poolID]
359		// The store lock makes the capacity check and the charge atomic, so
360		// concurrent writes can never overcommit the pool, and a failed write
361		// leaves the old object and its metadata untouched.
362		if p.allocated() > p.rawCapacity-(size-oldSize) {
363			writeError(w, http.StatusConflict, "insufficient_capacity")
364			return
365		}
366		b.objects[key] = &object{key: key, content: content, metadata: metadata, etag: etag, sizeBytes: size}
367		p.objectBytes += size - oldSize
368		// An overwrite is recorded even when the size delta is zero.
369		resource := bucketPath + "/" + bucketID + "/objects/" + key
370		if existing != nil {
371			s.appendAudit(auditObjectOverwritten, resource, b.poolID, size-oldSize)
372		} else {
373			s.appendAudit(auditObjectCreated, resource, b.poolID, size)
374		}
375		status := http.StatusCreated
376		if existing != nil {
377			status = http.StatusOK
378		}
379		w.Header().Set("ETag", etag)
380		writeJSON(w, status, b.objects[key].view())
381	}
382	
383	// getObject serves both GET and HEAD; headOnly suppresses the body.
384	func (s *store) getObject(w http.ResponseWriter, r *http.Request, bucketID, key string, headOnly bool) {
385		if !validID(bucketID) || !validObjectKey(key) {
386			writeError(w, http.StatusBadRequest, "invalid_request")
387			return
388		}
389		if r.URL.RawQuery != "" {
390			writeError(w, http.StatusBadRequest, "invalid_request")
391			return
392		}
393		s.mu.RLock()
394		b, ok := s.buckets[bucketID]
395		var o *object
396		if ok {
397			o = b.objects[key]
398		}
399		s.mu.RUnlock()
400		if !ok {
401			writeError(w, http.StatusNotFound, "bucket_not_found")
402			return
403		}
404		if o == nil {
405			writeError(w, http.StatusNotFound, "object_not_found")
406			return
407		}
408		for name, value := range o.metadata {
409			w.Header().Set(metaPrefix+name, value)
410		}
411		w.Header().Set("ETag", o.etag)
412		w.Header().Set("Content-Type", "application/octet-stream")
413		w.Header().Set("Content-Length", strconv.FormatInt(o.sizeBytes, 10))
414		w.WriteHeader(http.StatusOK)
415		if !headOnly {
416			_, _ = w.Write(o.content)
417		}
418	}
419	
420	func (s *store) deleteObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
421		if !validID(bucketID) || !validObjectKey(key) {
422			writeError(w, http.StatusBadRequest, "invalid_request")
423			return
424		}
425		if r.URL.RawQuery != "" {
426			writeError(w, http.StatusBadRequest, "invalid_request")
427			return
428		}
429		s.mu.Lock()
430		defer s.mu.Unlock()
431		b, ok := s.buckets[bucketID]
432		if !ok {
433			writeError(w, http.StatusNotFound, "bucket_not_found")
434			return
435		}
436		// Deleting an unknown or already-deleted object is a success with no
437		// state change, so only a real deletion records an event.
438		if o, exists := b.objects[key]; exists {
439			s.pools[b.poolID].objectBytes -= o.sizeBytes
440			delete(b.objects, key)
441			s.appendAudit(auditObjectDeleted, bucketPath+"/"+bucketID+"/objects/"+key, b.poolID, -o.sizeBytes)
442		}
443		w.WriteHeader(http.StatusNoContent)
444	}
445	
446	// parsePrefixQuery accepts an empty query or exactly one "prefix=<value>"
447	// pair. Duplicated or unknown parameters yield ok=false.
448	func parsePrefixQuery(raw string) (string, bool) {
449		if raw == "" {
450			return "", true
451		}
452		var prefix string
453		found := false
454		for _, pair := range strings.Split(raw, "&") {
455			k, value, ok := strings.Cut(pair, "=")
456			if !ok {
457				return "", false
458			}
459			decodedKey, err := url.QueryUnescape(k)
460			if err != nil || decodedKey != "prefix" || found {
461				return "", false
462			}
463			decodedValue, err := url.QueryUnescape(value)
464			if err != nil {
465				return "", false
466			}
467			prefix, found = decodedValue, true
468		}
469		return prefix, found
470	}
471	
472	func (s *store) listObjects(w http.ResponseWriter, r *http.Request, bucketID string) {
473		prefix, ok := parsePrefixQuery(r.URL.RawQuery)
474		if !ok || !validID(bucketID) {
475			writeError(w, http.StatusBadRequest, "invalid_request")
476			return
477		}
478		s.mu.RLock()
479		b, ok := s.buckets[bucketID]
480		var items []objectView
481		if ok {
482			keys := make([]string, 0, len(b.objects))
483			for k := range b.objects {
484				keys = append(keys, k)
485			}
486			sort.Strings(keys)
487			items = make([]objectView, 0, len(keys))
488			for _, k := range keys {
489				if strings.HasPrefix(k, prefix) {
490					items = append(items, b.objects[k].view())
491				}
492			}
493		}
494		s.mu.RUnlock()
495		if !ok {
496			writeError(w, http.StatusNotFound, "bucket_not_found")
497			return
498		}
499		writeJSON(w, http.StatusOK, map[string]any{"items": items})
500	}
