package server

import (
	"net/http"
	"sort"
)

type createSnapshotInput struct {
	ID                 string `json:"id"`
	ExpectedGeneration *int64 `json:"expectedGeneration"`
}

type createCloneInput struct {
	ID     string `json:"id"`
	PoolID string `json:"poolId"`
}

// snapshotView is the public representation of an in-memory volume snapshot.
type snapshotView struct {
	ID               string `json:"id"`
	SourceVolumeID   string `json:"sourceVolumeId"`
	PoolID           string `json:"poolId"`
	SizeBytes        int64  `json:"sizeBytes"`
	SourceGeneration int64  `json:"sourceGeneration"`
}

// snapshot is an immutable, in-memory copy of a volume's size at a given
// generation. It deliberately does not reference the live source volume: once
// taken it is independent, so later changes to or deletion of the source do
// not affect it. Its size charges the source pool until the snapshot is
// deleted.
type snapshot struct {
	id               string
	sourceVolumeID   string
	poolID           string
	sizeBytes        int64
	sourceGeneration int64
}

func (s *snapshot) view() snapshotView {
	return snapshotView{
		ID:               s.id,
		SourceVolumeID:   s.sourceVolumeID,
		PoolID:           s.poolID,
		SizeBytes:        s.sizeBytes,
		SourceGeneration: s.sourceGeneration,
	}
}

// routeSnapshots dispatches /v1/snapshots and its sub-paths.
func (s *store) routeSnapshots(w http.ResponseWriter, r *http.Request) {
	parts := splitPath(r.URL.Path, snapshotPath)
	for _, seg := range parts {
		if seg == "" {
			writeError(w, http.StatusNotFound, "not_found")
			return
		}
	}
	switch {
	case len(parts) == 0:
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		s.listSnapshots(w)
	case len(parts) == 1:
		switch r.Method {
		case http.MethodGet:
			s.getSnapshot(w, parts[0])
		case http.MethodDelete:
			s.deleteSnapshot(w, parts[0])
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodDelete)
		}
	case len(parts) == 2 && parts[1] == "clones":
		if r.Method != http.MethodPost {
			methodNotAllowed(w, http.MethodPost)
			return
		}
		s.createClone(w, r, parts[0])
	default:
		writeError(w, http.StatusNotFound, "not_found")
	}
}

func (s *store) listSnapshots(w http.ResponseWriter) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	ids := make([]string, 0, len(s.snapshots))
	for id := range s.snapshots {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	items := make([]snapshotView, 0, len(ids))
	for _, id := range ids {
		items = append(items, s.snapshots[id].view())
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *store) getSnapshot(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.RLock()
	snap, ok := s.snapshots[id]
	var view snapshotView
	if ok {
		view = snap.view()
	}
	s.mu.RUnlock()
	if !ok {
		writeError(w, http.StatusNotFound, "snapshot_not_found")
		return
	}
	writeJSON(w, http.StatusOK, view)
}

// createSnapshot handles POST /v1/volumes/{volumeId}/snapshots.
func (s *store) createSnapshot(w http.ResponseWriter, r *http.Request, volumeID string) {
	var in createSnapshotInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if !validID(volumeID) || !validID(in.ID) || in.ExpectedGeneration == nil || *in.ExpectedGeneration < 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	expected := *in.ExpectedGeneration

	s.mu.Lock()
	defer s.mu.Unlock()
	// A retry of the same id wins its idempotency/conflict check before the
	// source is looked up, so deleting the source after a successful snapshot
	// keeps the retry returning 200.
	if existing, dup := s.snapshots[in.ID]; dup {
		if existing.sourceVolumeID == volumeID && existing.sourceGeneration == expected {
			writeJSON(w, http.StatusOK, existing.view())
			return
		}
		writeError(w, http.StatusConflict, "snapshot_exists")
		return
	}
	v, ok := s.volumes[volumeID]
	if !ok {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	if v.binding != "" {
		writeError(w, http.StatusConflict, "volume_in_use")
		return
	}
	if v.generation != expected {
		writeError(w, http.StatusConflict, "stale_generation")
		return
	}
	p := s.pools[v.poolID]
	// The store lock makes the capacity check and charge atomic, so
	// concurrent snapshots can never overcommit the pool.
	if p.allocated() > p.rawCapacity-v.sizeBytes {
		writeError(w, http.StatusConflict, "insufficient_capacity")
		return
	}
	snap := &snapshot{
		id:               in.ID,
		sourceVolumeID:   volumeID,
		poolID:           v.poolID,
		sizeBytes:        v.sizeBytes,
		sourceGeneration: v.generation,
	}
	s.snapshots[in.ID] = snap
	p.snapshotBytes += v.sizeBytes
	s.appendAudit(auditSnapshotCreated, snapshotPath+"/"+in.ID, v.poolID, v.sizeBytes)
	writeJSON(w, http.StatusCreated, snap.view())
}

func (s *store) deleteSnapshot(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	snap, ok := s.snapshots[id]
	if !ok {
		writeError(w, http.StatusNotFound, "snapshot_not_found")
		return
	}
	s.pools[snap.poolID].snapshotBytes -= snap.sizeBytes
	delete(s.snapshots, id)
	s.appendAudit(auditSnapshotDeleted, snapshotPath+"/"+id, snap.poolID, -snap.sizeBytes)
	w.WriteHeader(http.StatusNoContent)
}

// createClone handles POST /v1/snapshots/{id}/clones.
func (s *store) createClone(w http.ResponseWriter, r *http.Request, snapshotID string) {
	var in createCloneInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if !validID(snapshotID) || !validID(in.ID) || !validID(in.PoolID) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	snap, ok := s.snapshots[snapshotID]
	if !ok {
		writeError(w, http.StatusNotFound, "snapshot_not_found")
		return
	}
	// A clone is an ordinary volume, so its id shares the global volume
	// namespace. Once the snapshot is confirmed, the volume-id conflict check
	// decides: a retry from the same snapshot into the same pool is 200, while
	// an id owned by any other creation or a different pool is 409.
	if existing, dup := s.volumes[in.ID]; dup {
		if existing.cloneSource == snapshotID && existing.poolID == in.PoolID {
			writeJSON(w, http.StatusOK, existing.view())
			return
		}
		writeError(w, http.StatusConflict, "volume_exists")
		return
	}
	target, ok := s.pools[in.PoolID]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	if target.allocated() > target.rawCapacity-snap.sizeBytes {
		writeError(w, http.StatusConflict, "insufficient_capacity")
		return
	}
	v := &volume{id: in.ID, poolID: in.PoolID, sizeBytes: snap.sizeBytes, cloneSource: snapshotID}
	s.volumes[in.ID] = v
	target.volumeBytes += snap.sizeBytes
	s.appendAudit(auditCloneCreated, volumePath+"/"+in.ID, in.PoolID, snap.sizeBytes)
	writeJSON(w, http.StatusCreated, v.view())
}

package server

import (
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
)

// auditAction enumerates the recorded state-changing operations. Failures,
// read-only requests and successful requests that change no state are never
// recorded.
type auditAction string

const (
	auditPoolCreated        auditAction = "pool.created"
	auditPoolDeleted        auditAction = "pool.deleted"
	auditReservationCreated auditAction = "reservation.created"
	auditReservationDeleted auditAction = "reservation.deleted"
	auditVolumeCreated      auditAction = "volume.created"
	auditVolumeDeleted      auditAction = "volume.deleted"
	auditVolumeBound        auditAction = "volume.bound"
	auditVolumeUnbound      auditAction = "volume.unbound"
	auditSnapshotCreated    auditAction = "snapshot.created"
	auditSnapshotDeleted    auditAction = "snapshot.deleted"
	auditCloneCreated       auditAction = "clone.created"
	auditBucketCreated      auditAction = "bucket.created"
	auditBucketDeleted      auditAction = "bucket.deleted"
	auditObjectCreated      auditAction = "object.created"
	auditObjectOverwritten  auditAction = "object.overwritten"
	auditObjectDeleted      auditAction = "object.deleted"
)

// auditEventView is the public representation of an audit event.
type auditEventView struct {
	Sequence   int64  `json:"sequence"`
	Action     string `json:"action"`
	Resource   string `json:"resource"`
	PoolID     string `json:"poolId"`
	BytesDelta int64  `json:"bytesDelta"`
}

// auditEvent is one entry of the in-memory audit log. Events are appended
// while holding the store write lock in the same critical section as the
// business state and capacity counters, so an event and the change it
// describes commit atomically: a committed response is always followed by a
// visible event, and a failure leaves no event. The log lives in memory and
// is wiped on restart.
type auditEvent struct {
	sequence   int64
	action     auditAction
	resource   string
	poolID     string
	bytesDelta int64
}

func (e *auditEvent) view() auditEventView {
	return auditEventView{
		Sequence:   e.sequence,
		Action:     string(e.action),
		Resource:   e.resource,
		PoolID:     e.poolID,
		BytesDelta: e.bytesDelta,
	}
}

// appendAudit assigns the next sequence and appends an event. The caller must
// hold s.mu for writing; numbering inside the commit critical section orders
// concurrent commits by the order in which they actually committed.
func (s *store) appendAudit(action auditAction, resource, poolID string, bytesDelta int64) {
	s.auditSeq++
	s.auditEvents = append(s.auditEvents, auditEvent{
		sequence:   s.auditSeq,
		action:     action,
		resource:   resource,
		poolID:     poolID,
		bytesDelta: bytesDelta,
	})
}

// auditEventsPath is the route constant for the audit events endpoint.
const auditEventsPath = "/v1/audit-events"

// auditEventsQuery is the parsed GET /v1/audit-events query.
type auditEventsQuery struct {
	after   int64
	limit   int
	poolID  string
	hasPool bool
}

// parseAuditEventsQuery accepts an empty query or any combination of the
// "after", "limit" and "poolId" parameters, each given at most once and always
// with a value. Defaults are after=0, limit=100, no pool filter. Duplicated,
// unknown, value-less or malformed parameters yield ok=false.
func parseAuditEventsQuery(raw string) (auditEventsQuery, bool) {
	q := auditEventsQuery{limit: 100}
	if raw == "" {
		return q, true
	}
	seenAfter, seenLimit, seenPool := false, false, false
	for _, pair := range strings.Split(raw, "&") {
		k, value, found := strings.Cut(pair, "=")
		if !found {
			return q, false
		}
		key, err := url.QueryUnescape(k)
		if err != nil {
			return q, false
		}
		decoded, err := url.QueryUnescape(value)
		if err != nil {
			return q, false
		}
		switch key {
		case "after":
			if seenAfter || !isNonNegativeDecimal(decoded) {
				return q, false
			}
			seenAfter = true
			n, err := strconv.ParseInt(decoded, 10, 64)
			if err != nil {
				return q, false
			}
			q.after = n
		case "limit":
			if seenLimit || !isNonNegativeDecimal(decoded) {
				return q, false
			}
			seenLimit = true
			n, err := strconv.ParseInt(decoded, 10, 64)
			if err != nil || n < 1 || n > 1000 {
				return q, false
			}
			q.limit = int(n)
		case "poolId":
			if seenPool || decoded == "" || !validID(decoded) {
				return q, false
			}
			seenPool = true
			q.poolID = decoded
			q.hasPool = true
		default:
			return q, false
		}
	}
	return q, true
}

// isNonNegativeDecimal reports whether s is one or more ASCII decimal digits,
// rejecting signs, spaces and exponent notation.
func isNonNegativeDecimal(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// auditEventsList is the response envelope.
type auditEventsList struct {
	Items     []auditEventView `json:"items"`
	NextAfter int64            `json:"nextAfter"`
	HasMore   bool             `json:"hasMore"`
}

// listAuditEvents handles GET /v1/audit-events. The whole page is selected
// under a single read lock, so items and hasMore describe one consistent read
// state even while other requests commit new events.
func (s *store) listAuditEvents(w http.ResponseWriter, r *http.Request) {
	q, ok := parseAuditEventsQuery(r.URL.RawQuery)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.RLock()
	defer s.mu.RUnlock()
	if q.hasPool {
		if _, exists := s.pools[q.poolID]; !exists {
			writeError(w, http.StatusNotFound, "pool_not_found")
			return
		}
	}

	// Sequences are dense and the slice is append-only, so index order is
	// sequence order. Jump to the first event with sequence > after.
	first := sort.Search(len(s.auditEvents), func(i int) bool {
		return s.auditEvents[i].sequence > q.after
	})
	items := make([]auditEventView, 0, q.limit)
	hasMore := false
	for i := first; i < len(s.auditEvents); i++ {
		e := s.auditEvents[i]
		if q.hasPool && e.poolID != q.poolID {
			continue
		}
		if len(items) >= q.limit {
			// A matching event beyond the page (in this same read state)
			// remains.
			hasMore = true
			break
		}
		items = append(items, e.view())
	}
	nextAfter := q.after
	if len(items) > 0 {
		nextAfter = items[len(items)-1].Sequence
	}
	writeJSON(w, http.StatusOK, auditEventsList{Items: items, NextAfter: nextAfter, HasMore: hasMore})
}

package server

import (
	"fmt"
	"net/http"
	"net/url"
	"sort"
	"strings"
)

// capacityReportItem is the per-pool row of the capacity report.
type capacityReportItem struct {
	PoolID           string `json:"poolId"`
	RawCapacityBytes int64  `json:"rawCapacityBytes"`
	ReservationBytes int64  `json:"reservationBytes"`
	VolumeBytes      int64  `json:"volumeBytes"`
	SnapshotBytes    int64  `json:"snapshotBytes"`
	ObjectBytes      int64  `json:"objectBytes"`
	AllocatedBytes   int64  `json:"allocatedBytes"`
	AvailableBytes   int64  `json:"availableBytes"`
}

// capacityReportSummary is the aggregate over every reported pool; it carries
// the same fields as a pool row except poolId.
type capacityReportSummary struct {
	RawCapacityBytes int64 `json:"rawCapacityBytes"`
	ReservationBytes int64 `json:"reservationBytes"`
	VolumeBytes      int64 `json:"volumeBytes"`
	SnapshotBytes    int64 `json:"snapshotBytes"`
	ObjectBytes      int64 `json:"objectBytes"`
	AllocatedBytes   int64 `json:"allocatedBytes"`
	AvailableBytes   int64 `json:"availableBytes"`
}

// csvHeader is the fixed first line of the CSV report. Pool ids are
// restricted to A-Za-z0-9._- so no field ever needs quoting.
const csvHeader = "poolId,rawCapacityBytes,reservationBytes,volumeBytes,snapshotBytes,objectBytes,allocatedBytes,availableBytes"

// parseCapacityReportQuery accepts an empty query or any combination of the
// "format" and "poolId" parameters, each given at most once and always with
// a value. Duplicated, unknown or value-less parameters yield ok=false.
func parseCapacityReportQuery(raw string) (format, poolID string, hasPool, ok bool) {
	format = "json"
	if raw == "" {
		return format, "", false, true
	}
	seenFormat, seenPool := false, false
	for _, pair := range strings.Split(raw, "&") {
		k, value, found := strings.Cut(pair, "=")
		if !found {
			return "", "", false, false
		}
		key, err := url.QueryUnescape(k)
		if err != nil {
			return "", "", false, false
		}
		decoded, err := url.QueryUnescape(value)
		if err != nil {
			return "", "", false, false
		}
		switch key {
		case "format":
			if seenFormat {
				return "", "", false, false
			}
			seenFormat = true
			format = decoded
		case "poolId":
			if seenPool {
				return "", "", false, false
			}
			seenPool = true
			poolID = decoded
		default:
			return "", "", false, false
		}
	}
	return format, poolID, seenPool, true
}

// capacityReport handles GET /v1/capacity-report. The whole report is built
// under a single read lock, so every row and the summary describe one
// consistent state even while other requests mutate the store.
func (s *store) capacityReport(w http.ResponseWriter, r *http.Request) {
	format, poolID, hasPool, ok := parseCapacityReportQuery(r.URL.RawQuery)
	if !ok || (format != "json" && format != "csv") || (hasPool && !validID(poolID)) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.RLock()
	var ids []string
	if hasPool {
		if _, exists := s.pools[poolID]; !exists {
			s.mu.RUnlock()
			writeError(w, http.StatusNotFound, "pool_not_found")
			return
		}
		ids = []string{poolID}
	} else {
		ids = make([]string, 0, len(s.pools))
		for id := range s.pools {
			ids = append(ids, id)
		}
		sort.Strings(ids)
	}
	items := make([]capacityReportItem, 0, len(ids))
	var summary capacityReportSummary
	for _, id := range ids {
		p := s.pools[id]
		var reservationBytes int64
		for _, res := range p.reservations {
			reservationBytes += res.bytes
		}
		allocated := p.allocated()
		item := capacityReportItem{
			PoolID:           p.id,
			RawCapacityBytes: p.rawCapacity,
			ReservationBytes: reservationBytes,
			VolumeBytes:      p.volumeBytes,
			SnapshotBytes:    p.snapshotBytes,
			ObjectBytes:      p.objectBytes,
			AllocatedBytes:   allocated,
			AvailableBytes:   p.rawCapacity - allocated,
		}
		items = append(items, item)
		summary.RawCapacityBytes += item.RawCapacityBytes
		summary.ReservationBytes += item.ReservationBytes
		summary.VolumeBytes += item.VolumeBytes
		summary.SnapshotBytes += item.SnapshotBytes
		summary.ObjectBytes += item.ObjectBytes
		summary.AllocatedBytes += item.AllocatedBytes
		summary.AvailableBytes += item.AvailableBytes
	}
	s.mu.RUnlock()

	if format == "csv" {
		var b strings.Builder
		b.WriteString(csvHeader)
		b.WriteByte('\n')
		for _, it := range items {
			fmt.Fprintf(&b, "%s,%d,%d,%d,%d,%d,%d,%d\n",
				it.PoolID, it.RawCapacityBytes, it.ReservationBytes, it.VolumeBytes,
				it.SnapshotBytes, it.ObjectBytes, it.AllocatedBytes, it.AvailableBytes)
		}
		w.Header().Set("Content-Type", "text/csv; charset=utf-8")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(b.String()))
		return
	}
	writeJSON(w, http.StatusOK, struct {
		Summary capacityReportSummary `json:"summary"`
		Items   []capacityReportItem  `json:"items"`
	}{Summary: summary, Items: items})
}

